import type { FrameworkApiReference } from '../types'
import { mastraLearningMeta } from './learning-meta'

type MastraApiInput = Omit<FrameworkApiReference, 'slug' | 'technologySlug' | 'maturity' | 'exampleLanguage' | 'officialUrl'> & {
  path: string
  maturity?: FrameworkApiReference['maturity']
}

const mastraApi = ({ path, maturity = 'stable', ...input }: MastraApiInput): FrameworkApiReference => {
  const learningMeta = mastraLearningMeta[input.name as keyof typeof mastraLearningMeta]
  if (!learningMeta) throw new Error(`Missing structured Mastra learning metadata for ${input.name}`)
  return {
    ...input,
    ...learningMeta,
    slug: `mastra-${input.name.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase()}`,
    technologySlug: 'mastra',
    maturity,
    exampleLanguage: 'ts',
    officialUrl: `https://mastra.ai/reference/${path}`,
  }
}

const coreApis = [
  mastraApi({ name: 'Mastra', group: '核心注册中心', kind: 'class', path: 'core/mastra-class', signature: 'new Mastra(config: MastraConfig)', beginner: 'Mastra 是整个应用的“总装配台”：把 agent、workflow、tool、memory、vector、storage、logger 和 observability 用名字注册到同一个运行时里。后续代码只需拿到 mastra 实例，就能按名字找到这些能力。', whenToUse: '应用启动时创建一次，集中完成依赖装配、生命周期管理和服务端暴露；不要在每次请求中重复 new。', example: `import { Mastra } from '@mastra/core/mastra'\n\nexport const mastra = new Mastra({\n  agents: { interviewer },\n  workflows: { interviewFlow },\n  logger,\n})`, returns: '一个 Mastra 应用实例；它保存已注册资源并向 Studio、Server、Agent 和 Workflow 提供统一访问入口。', interview: '面试可以把它解释为“依赖注入容器 + AI 资源注册表”。关键价值不是简单聚合对象，而是统一资源命名、运行上下文、存储、日志和可观测性。', pitfall: '注册对象的键名和资源自身 id 不一定相同；按键查找与按 id 查找要分清，并避免创建多个实例导致资源和存储上下文割裂。' }),
  mastraApi({ name: 'Mastra.addGateway', group: '核心注册中心', kind: 'function', path: 'core/addGateway', signature: 'mastra.addGateway(gateway: MastraModelGateway): void', beginner: '运行时给 Mastra 增加一个模型网关。模型网关负责把统一的模型请求路由到实际供应商，并可集中处理鉴权或模型发现。', whenToUse: '网关不能在构造阶段静态确定，或插件启动后才获得网关配置时。', example: `mastra.addGateway(myGateway)\nconst gateway = mastra.getGatewayById(myGateway.id)`, returns: '不返回业务数据；注册成功后可通过 getGateway、getGatewayById 或 listGateways 取回。', interview: '这是注册表的可变扩展点。要说明动态注册方便插件化，但并发修改、重复 id 和配置热更新都需要明确治理策略。', pitfall: '不要把请求级临时对象注册成全局网关；还要确保 id 唯一，并在接收流量前完成注册。' }),
  mastraApi({ name: 'Mastra.getAgent', group: '核心注册中心', kind: 'function', path: 'core/getAgent', signature: 'mastra.getAgent<TAgent>(name: string): TAgent', beginner: '用注册时对象键名取出一个 Agent，例如 agents: { interviewer } 中的 interviewer。它像从工具柜按抽屉标签拿东西。', whenToUse: '服务路由、Workflow 或测试代码已知注册键名，需要调用该 Agent 的 generate、stream 等方法时。', example: `const agent = mastra.getAgent('interviewer')\nconst result = await agent.generate('介绍一下闭包')`, returns: '匹配名字的 Agent 实例；名字不存在时会抛出错误，而不是返回一个可安全忽略的空值。', interview: '强调 name 是 Mastra 配置映射的 key；它提供类型推断和集中依赖访问，但字符串动态化会削弱编译期保证。', pitfall: '不要把 Agent 自身 id 当作配置键名；需要按 id 搜索时使用 getAgentById。' }),
  mastraApi({ name: 'Mastra.getAgentById', group: '核心注册中心', kind: 'function', path: 'core/getAgentById', signature: 'mastra.getAgentById(id: string): Agent | undefined', beginner: '遍历已注册 Agent，按 Agent 构造参数里的 id 查找，而不是按注册对象的键名查找。', whenToUse: '外部数据只保存资源 id，或者 Studio、数据库记录和 API 参数使用 Agent id 时。', example: `const agent = mastra.getAgentById('interview-agent')\nif (!agent) throw new Error('Agent 不存在')`, returns: '找到时返回 Agent，找不到时返回 undefined，因此调用方必须处理缺失分支。', interview: 'name lookup 通常是配置键的直接访问，id lookup 是资源身份查询；一个用于代码装配，一个更适合持久化和外部协议。', pitfall: '不要直接对可能为 undefined 的结果调用 generate；同时应保证不同注册键下没有重复的 Agent id。' }),
  mastraApi({ name: 'Mastra.getGateway', group: '核心注册中心', kind: 'function', path: 'core/getGateway', signature: 'mastra.getGateway(name: string): MastraModelGateway', beginner: '按注册键名拿到模型网关，让应用查询模型或通过统一入口路由模型请求。', whenToUse: '已经在 Mastra 配置中注册多个网关，需要按环境或业务名字选择其中一个时。', example: `const gateway = mastra.getGateway('primaryGateway')\nconst models = await gateway.listModels()`, returns: '对应的 MastraModelGateway；键名无效时抛错。', interview: '网关把模型选择与 Agent 业务逻辑解耦，是供应商切换、集中鉴权和模型目录治理的边界。', pitfall: '不要在业务代码里同时混用网关名、网关 id 和供应商名；应定义一套稳定映射。' }),
  mastraApi({ name: 'Mastra.getGatewayById', group: '核心注册中心', kind: 'function', path: 'core/getGatewayById', signature: 'mastra.getGatewayById(id: string): MastraModelGateway | undefined', beginner: '按网关自身 id 查找注册项，适合从配置文件、数据库或请求参数恢复网关选择。', whenToUse: '调用方只有稳定资源 id，而不知道 Mastra 配置对象使用了什么键名时。', example: `const gateway = mastra.getGatewayById('company-router')\nif (!gateway) throw new Error('未知模型网关')`, returns: '找到的网关实例或 undefined。', interview: '与 getGateway 的差别仍是“装配名称”和“资源身份”；外部输入必须做白名单和缺失处理。', pitfall: '不要让用户提交任意 id 就获得未授权网关；多租户系统还要校验租户边界。' }),
  mastraApi({ name: 'Mastra.getLogger', group: '核心注册中心', kind: 'function', path: 'core/getLogger', signature: 'mastra.getLogger(): IMastraLogger', beginner: '取得 Mastra 当前使用的统一日志器，业务扩展代码可以和框架日志保持相同格式、级别和输出位置。', whenToUse: '自定义路由、工具或启动逻辑需要记录结构化日志，并希望复用 Mastra 的日志配置时。', example: `const logger = mastra.getLogger()\nlogger.info('interview started', { resourceId })`, returns: '当前 IMastraLogger 实例。', interview: '统一 logger 让 trace id、资源 id 和结构化字段贯穿框架与业务日志，是可观测性关联分析的基础。', pitfall: '不要记录 prompt、令牌或个人信息的原文；日志字段也应做脱敏和采样。' }),
  mastraApi({ name: 'Mastra.getMemory', group: '核心注册中心', kind: 'function', path: 'core/getMemory', signature: 'mastra.getMemory(name?: string): Memory | undefined', beginner: '从 Mastra 的内存注册表取出 Memory 实例。Memory 管的是线程、消息历史、工作记忆和语义召回，不是 JavaScript 进程内的临时变量。', whenToUse: '管理对话线程、查询历史或让多个 Agent 共享同一套持久化记忆时。', example: `const memory = mastra.getMemory('sharedMemory')\nif (!memory) throw new Error('Memory 未配置')`, returns: '指定或默认的 Memory 实例；未配置时可能得到 undefined。', interview: 'Memory 是对话状态的领域层，Storage 是持久化基础设施；二者不可混为一谈。', pitfall: '调用前处理 undefined；多租户场景必须始终携带 resourceId，不能只用 threadId 隔离用户。' }),
  mastraApi({ name: 'Mastra.getScorer', group: '核心注册中心', kind: 'function', path: 'core/getScorer', signature: 'mastra.getScorer(name: string): MastraScorer', beginner: '按注册键取出评分器。评分器把“回答好不好”变成可重复执行的计算，而不是只靠人工感觉。', whenToUse: '在线反馈、离线评测、CI 门禁或回归测试需要调用已注册 scorer 时。', example: `const scorer = mastra.getScorer('answerRelevancy')\nconst score = await scorer.run({ input, output })`, returns: '对应的 MastraScorer 实例；名字错误时抛错。', interview: 'Scorer 将质量标准代码化，需区分规则评分、统计评分与模型裁判，并关注裁判漂移和成本。', pitfall: '单个分数不能代表整体质量；必须保存样本、评分理由、模型版本并组合多个维度。' }),
  mastraApi({ name: 'Mastra.getScorerById', group: '核心注册中心', kind: 'function', path: 'core/getScorerById', signature: 'mastra.getScorerById(id: string): MastraScorer | undefined', beginner: '按评分器自身 id 查找，适合评测任务或数据库记录只保存 scorer id 的情况。', whenToUse: '从持久化实验配置恢复评分器，或外部接口传入稳定 scorer id 时。', example: `const scorer = mastra.getScorerById(config.scorerId)\nif (!scorer) throw new Error('评分器不存在')`, returns: '评分器实例或 undefined。', interview: '说明资源 id 是跨进程、跨配置的稳定标识，但动态选择 scorer 仍需版本和权限治理。', pitfall: '不要静默跳过缺失评分器，否则评测报告会出现“看似通过、实际没评”的假阳性。' }),
  mastraApi({ name: 'Mastra.getStorage', group: '核心注册中心', kind: 'function', path: 'core/getStorage', signature: 'mastra.getStorage(): MastraStorage | undefined', beginner: '取得 Mastra 的持久化存储适配器。它保存 workflow 快照、memory、评测或 trace 等框架数据，具体能力取决于适配器。', whenToUse: '自定义扩展需要访问同一存储，或启动健康检查需要确认 storage 已配置时。', example: `const storage = mastra.getStorage()\nif (!storage) throw new Error('生产环境必须配置持久化')`, returns: '当前 MastraStorage，未设置时为 undefined。', interview: 'Storage 是框架各模块共享的基础设施；生产设计要讨论一致性、迁移、连接池、保留策略和故障恢复。', pitfall: '不要假设默认内存存储可跨重启；也不要直接依赖某数据库的私有方法破坏适配器可替换性。' }),
  mastraApi({ name: 'Mastra.getTool', group: '核心注册中心', kind: 'function', path: 'core/getTool', signature: 'mastra.getTool(name: string): ToolAction', beginner: '按注册键名拿到一个 Tool。Tool 是带输入输出 schema 的受控函数，可以被 Agent 调用，也可以被代码直接执行。', whenToUse: '路由、测试或 workflow 需要复用已注册工具，而不是重新构造一份时。', example: `const tool = mastra.getTool('searchDocs')\nconst result = await tool.execute?.({ query: 'RAG' }, context)`, returns: '对应的 ToolAction；名字无效时抛错。', interview: '工具注册表让 schema、权限、执行实现和 Agent 暴露方式保持同源，避免复制两套业务动作。', pitfall: '直接 execute 仍需提供工具期望的执行上下文；不要绕过鉴权、审批和输入验证。' }),
  mastraApi({ name: 'Mastra.getToolById', group: '核心注册中心', kind: 'function', path: 'core/getToolById', signature: 'mastra.getToolById(id: string): ToolAction | undefined', beginner: '按 Tool 自身 id 查找，而不是按配置对象的键名取值。', whenToUse: '任务记录、审批记录或外部协议保存的是工具 id 时。', example: `const tool = mastra.getToolById(request.toolId)\nif (!tool) throw new Error('工具不存在')`, returns: '工具实例或 undefined。', interview: '外部 id 驱动工具执行时，本质是命令分发；必须做允许列表、参数校验和审计。', pitfall: '不要把 getToolById 当权限检查；查得到只代表已注册，不代表当前用户可以执行。' }),
  mastraApi({ name: 'Mastra.getVector', group: '核心注册中心', kind: 'function', path: 'core/getVector', signature: 'mastra.getVector(name: string): MastraVector', beginner: '按注册名取得向量库适配器，用它创建索引、写入向量、相似度查询或删除数据。', whenToUse: 'RAG 入库和检索代码需要访问统一注册的向量后端时。', example: `const vector = mastra.getVector('knowledgeBase')\nconst hits = await vector.query({ indexName: 'docs', queryVector, topK: 5 })`, returns: '对应的 MastraVector 实例。', interview: '向量适配器隔离数据库差异，但索引维度、距离度量、metadata 过滤和租户隔离仍是应用必须明确的契约。', pitfall: '查询向量必须与入库使用同一 embedding 模型和维度；模型迁移通常需要重建索引。' }),
  mastraApi({ name: 'Mastra.getWorkflow', group: '核心注册中心', kind: 'function', path: 'core/getWorkflow', signature: 'mastra.getWorkflow<TWorkflow>(name: string): TWorkflow', beginner: '按注册键取得 Workflow 定义。Workflow 是已经 commit 的流程图，真正执行前还要 createRun。', whenToUse: 'API 路由、定时任务或 Agent 工具需要启动某条已注册流程时。', example: `const workflow = mastra.getWorkflow('interviewFlow')\nconst run = await workflow.createRun()\nconst result = await run.start({ inputData })`, returns: '对应的 Workflow 实例；名字无效时抛错。', interview: 'Workflow 定义与 Run 实例要分开：定义可复用，Run 承载一次执行的状态、快照和 runId。', pitfall: '不要把同一个 Run 对象复用于多次业务请求；每次执行应创建独立 Run。' }),
  mastraApi({ name: 'Mastra.listAgents', group: '核心注册中心', kind: 'function', path: 'core/listAgents', signature: 'mastra.listAgents(): Record<string, Agent>', beginner: '一次列出所有按配置键注册的 Agent，返回的是名字到 Agent 实例的映射。', whenToUse: '构建管理页面、健康检查、资源发现或测试注册完整性时。', example: `for (const [name, agent] of Object.entries(mastra.listAgents())) {\n  console.log(name, agent.id)\n}`, returns: '注册键到 Agent 的 Record。', interview: 'list API 适合资源发现，但不应直接作为公共接口返回整个实例；对外应转换成最小元数据 DTO。', pitfall: '不要把 Agent 对象序列化给浏览器，其中可能包含工具实现、模型配置和敏感运行依赖。' }),
  mastraApi({ name: 'Mastra.listGateways', group: '核心注册中心', kind: 'function', path: 'core/listGateways', signature: 'mastra.listGateways(): Record<string, MastraModelGateway>', beginner: '列出当前 Mastra 中注册的全部模型网关及其配置键名。', whenToUse: '启动自检、管理端模型目录或动态路由策略需要枚举网关时。', example: `const gateways = mastra.listGateways()\nconst names = Object.keys(gateways)`, returns: '注册键到网关实例的映射。', interview: '模型网关属于基础设施资源，枚举能力便于治理，但对外暴露时应隐藏凭据和内部拓扑。', pitfall: '不要把完整网关实例放进 API 响应；只输出经过筛选的 id、状态和可用模型信息。' }),
  mastraApi({ name: 'Mastra.listMemory', group: '核心注册中心', kind: 'function', path: 'core/listMemory', signature: 'mastra.listMemory(): Record<string, Memory>', beginner: '列出注册的所有 Memory 实例，帮助你确认不同 Agent 使用的是共享记忆还是独立记忆。', whenToUse: '启动诊断、管理页和自动化测试需要检查 Memory 装配时。', example: `const memories = mastra.listMemory()\nconsole.log(Object.keys(memories))`, returns: '注册键到 Memory 实例的映射。', interview: '多 Memory 设计常用于隔离业务域、合规边界或不同保留策略，而不是单纯按 Agent 拆分。', pitfall: '不要暴露 Memory 实例给客户端；管理接口也不能绕过 resourceId 读取任意线程。' }),
  mastraApi({ name: 'Mastra.listScorers', group: '核心注册中心', kind: 'function', path: 'core/listScorers', signature: 'mastra.listScorers(): Record<string, MastraScorer>', beginner: '列出所有已注册评分器，可用于给评测界面提供可选择的质量维度。', whenToUse: '实验平台、CI 或管理工具需要发现当前可用 scorer 时。', example: `const scorers = mastra.listScorers()\nconst ids = Object.values(scorers).map(s => s.id)`, returns: '注册键到 MastraScorer 的映射。', interview: '评分器目录应有版本、适用数据集和阈值元数据，否则同名分数跨版本不可比较。', pitfall: '不要默认对所有请求执行全部评分器；模型型 scorer 会增加显著延迟和费用。' }),
  mastraApi({ name: 'Mastra.listTools', group: '核心注册中心', kind: 'function', path: 'core/listTools', signature: 'mastra.listTools(): Record<string, ToolAction>', beginner: '列出 Mastra 顶层注册的全部工具，返回配置键到 Tool 的映射。', whenToUse: '工具目录、健康检查、测试或按策略给 Agent 选择工具时。', example: `const publicTools = Object.entries(mastra.listTools())\n  .filter(([name]) => allowList.has(name))`, returns: '所有顶层 ToolAction 的 Record。', interview: '“已注册”与“允许某 Agent/用户调用”是两层概念；生产系统需要额外的授权和审批策略。', pitfall: '绝不能把 listTools 的结果无条件全部交给模型，工具越多不仅风险更高，也会增加上下文和选错工具概率。' }),
  mastraApi({ name: 'Mastra.listVectors', group: '核心注册中心', kind: 'function', path: 'core/listVectors', signature: 'mastra.listVectors(): Record<string, MastraVector>', beginner: '列出注册的向量库适配器，便于查看当前应用有哪些知识库后端。', whenToUse: '多知识库路由、管理页面或启动检查需要发现 vector store 时。', example: `const vectors = mastra.listVectors()\nif (!vectors.knowledgeBase) throw new Error('缺少知识库')`, returns: '注册键到 MastraVector 的映射。', interview: '多向量库通常来自数据域、地区或租户隔离；检索层应通过明确路由选择，而不是随意遍历。', pitfall: '不要允许客户端直接决定任意向量库名字，否则可能越权查询其他租户或内部索引。' }),
  mastraApi({ name: 'Mastra.listWorkflows', group: '核心注册中心', kind: 'function', path: 'core/listWorkflows', signature: 'mastra.listWorkflows(): Record<string, Workflow>', beginner: '列出所有注册 Workflow 定义，让管理端或调度器知道系统能运行哪些确定性流程。', whenToUse: 'Workflow 目录、调度配置、Studio 集成和注册测试时。', example: `const workflows = mastra.listWorkflows()\nconsole.log(Object.keys(workflows))`, returns: '注册键到 Workflow 的映射。', interview: 'Workflow 可发现性有利于平台化，但启动权限、输入 schema 和版本必须分别治理。', pitfall: '不要用用户输入直接索引并启动任意 workflow；先做 allowlist 和 inputSchema 校验。' }),
  mastraApi({ name: 'Mastra.setLogger', group: '核心注册中心', kind: 'function', path: 'core/setLogger', signature: 'mastra.setLogger(logger: IMastraLogger): void', beginner: '替换 Mastra 当前的统一日志实现，后续框架与业务可把日志送到新的目的地。', whenToUse: '测试中注入捕获日志器，或启动阶段根据环境选择 Pino 等实现时。', example: `mastra.setLogger(new PinoLogger({ name: 'interview-api', level: 'info' }))`, returns: '无返回值；之后 getLogger 会取得新实例。', interview: '可替换 logger 是依赖反转，但生产热替换要考虑旧 logger 缓冲区 flush 和并发请求的一致性。', pitfall: '不要在高并发请求中频繁切换全局 logger；测试结束也要恢复隔离，避免用例互相污染。' }),
  mastraApi({ name: 'Mastra.setStorage', group: '核心注册中心', kind: 'function', path: 'core/setStorage', signature: 'mastra.setStorage(storage: MastraStorage): void', beginner: '给 Mastra 设置或替换持久化适配器，让 Memory、Workflow 等模块有稳定的数据后端。', whenToUse: '存储必须异步初始化后才能注入，或测试希望替换为隔离存储时。', example: `const storage = await createStorage()\nmastra.setStorage(storage)`, returns: '无返回值；之后 getStorage 返回新适配器。', interview: '存储替换是基础设施生命周期问题，必须在业务启动前完成，并确保 schema、迁移和现有模块引用一致。', pitfall: '不要在已有运行中的 Workflow 中途切换 storage；旧快照可能留在另一个后端，导致无法恢复。' }),
]

const agentApis = [
  mastraApi({ name: 'Agent', group: 'Agent 智能体', kind: 'class', path: 'agents/agent', signature: 'new Agent(config: AgentConfig)', beginner: 'Agent 是“带角色说明、模型、工具和记忆的执行者”。你给它消息，它会组合 instructions 与上下文，调用模型，必要时选择工具，再形成答案。', whenToUse: '任务需要模型自主判断、选择工具或维持多轮对话，而不是固定步骤的确定性流程时。', example: `import { Agent } from '@mastra/core/agent'\n\nconst interviewer = new Agent({\n  id: 'interviewer',\n  name: '前端面试官',\n  instructions: '先澄清问题，再用初学者语言回答。',\n  model: 'openai/gpt-5.5',\n  tools: { searchDocs },\n})`, returns: '一个可调用 generate、stream、network 等方法的 Agent 实例。', interview: 'Agent 的核心循环是“观察上下文 → 模型决策 → 工具行动 → 读取结果 → 继续或结束”。框架负责协议与编排，业务仍负责边界、权限和停止条件。', pitfall: 'instructions 不是安全边界；危险工具必须在执行层鉴权。工具过多、描述模糊或没有停止条件会提高误调用与无限循环风险。' }),
  mastraApi({ name: 'Agent.generate', group: 'Agent 智能体', kind: 'function', path: 'agents/generate', signature: 'agent.generate(messages, options?): Promise<MastraModelOutput>', beginner: '等待 Agent 完整运行结束后一次拿到结果，适合后台任务、分类和需要完整答案再继续的场景。messages 可以是字符串或消息数组，options 控制记忆、结构化输出、工具步数等。', whenToUse: '用户不需要逐字看到生成过程，或者下一段代码必须拿到完整 text、toolCalls、usage 和结构化结果时。', example: `const result = await interviewer.generate(\n  '请解释事件循环',\n  { memory: { thread: 't-1', resource: 'u-1' }, maxSteps: 5 },\n)\nconsole.log(result.text)`, returns: 'Promise<MastraModelOutput>，包含 text、steps、toolCalls、toolResults、usage、finishReason 等生成信息。', interview: 'generate 是非流式消费方式，但 Agent 内部仍可能经历多步工具循环。maxSteps 限制的是模型—工具往返，不等于 HTTP 超时。', pitfall: '长回答会让首屏一直等待；必须设置超时、重试和合理 maxSteps，并同时提供 thread 与 resource 防止记忆串用户。' }),
  mastraApi({ name: 'Agent.stream', group: 'Agent 智能体', kind: 'function', path: 'streaming/agents/stream', signature: 'agent.stream(messages, options?): Promise<MastraModelOutput>', beginner: '让 Agent 一边生成一边把文本、推理状态和工具事件送出来。返回对象提供 textStream/fullStream，也能转换成 Web Response。', whenToUse: '聊天、长答案、实时工具状态和首字延迟重要的交互界面。', example: `const result = await interviewer.stream('什么是 RAG？')\nfor await (const chunk of result.textStream) {\n  process.stdout.write(chunk)\n}`, returns: '可流式消费的 MastraModelOutput；同时保留最终 text、usage 等异步结果和响应转换方法。', interview: '流式降低的是感知延迟，不一定降低总耗时。生产回答还应提到背压、断线、取消、错误帧与工具事件协议。', pitfall: '不要只转发纯文本后声称保留完整 Agent 状态；工具调用、来源和错误需要使用 fullStream 或标准响应转换。' }),
  mastraApi({ name: 'Agent.streamUntilIdle', group: 'Agent 智能体', kind: 'function', path: 'streaming/agents/streamUntilIdle', signature: 'agent.streamUntilIdle(messages, options?): Promise<MastraModelOutput>', beginner: '启动流式 Agent，并持续等待它把当前可执行工作跑到“空闲”为止；它特别适合可能暂停、等待信号或后台继续的长运行 Agent。', whenToUse: '使用 durable agent、信号或异步任务，调用方希望消费到当前运行真正 idle，而不是第一轮模型输出就结束时。', example: `const output = await durableAgent.streamUntilIdle('整理本周反馈')\nfor await (const event of output.fullStream) {\n  handleEvent(event)\n}`, returns: '一个流式模型输出，直到 Agent 进入空闲/完成状态；可消费全量事件。', interview: 'idle 是调度语义，不只是“文本结束”。它把长运行 Agent 的一次活跃周期作为消费边界，便于服务端流和状态同步。', pitfall: '不能把 idle 当永久完成；后续信号仍可能唤醒任务。网络连接也要有超时和断线恢复策略。' }),
  mastraApi({ name: 'Agent.getDefaultOptions', group: 'Agent 智能体', kind: 'function', path: 'agents/getDefaultOptions', signature: 'agent.getDefaultOptions(options?: ResolveOptions): Promise<AgentDefaultOptions>', beginner: '解析 Agent 配置中可能是函数的默认生成/流式选项，得到这次运行真正会采用的模型参数、工具和处理器等配置。', whenToUse: '调试动态配置、构建检查页面，或扩展 Agent 运行逻辑前需要看到最终默认值时。', example: `const defaults = await interviewer.getDefaultOptions({ requestContext })\nconsole.log(defaults.modelSettings)`, returns: '解析后的 AgentDefaultOptions。', interview: '动态配置依赖 requestContext，因此“Agent 配置”不是永远固定的；可观察最终解析值有助于解释多租户差异。', pitfall: '不要把解析结果长期全局缓存，否则不同用户、租户或请求上下文可能错误复用同一配置。' }),
  mastraApi({ name: 'Agent.getDescription', group: 'Agent 智能体', kind: 'function', path: 'agents/getDescription', signature: 'agent.getDescription({ requestContext? }?): Promise<string | undefined>', beginner: '取得 Agent 的能力描述。描述可静态填写，也可根据请求上下文动态生成，Supervisor 会用它判断该把任务交给谁。', whenToUse: '展示 Agent 目录、构建多 Agent 路由或调试 Supervisor 的委派选择时。', example: `const description = await interviewer.getDescription({ requestContext })`, returns: '解析后的描述字符串；未配置时可能为 undefined。', interview: '多 Agent 系统中 description 类似工具描述，是路由质量的重要特征；应写能力、输入边界和不适用范围。', pitfall: '描述过度宽泛会让 Supervisor 频繁选错 Agent；动态描述也不能泄露请求上下文中的敏感信息。' }),
  mastraApi({ name: 'Agent.getInstructions', group: 'Agent 智能体', kind: 'function', path: 'agents/getInstructions', signature: 'agent.getInstructions({ requestContext? }?): Promise<DynamicArgument<AgentInstructions>>', beginner: '解析并返回 Agent 的系统指令。指令可以是字符串、消息、函数或多段组合，用来说明身份、目标、步骤和输出要求。', whenToUse: '调试最终 system prompt、做配置审计，或需要把 Agent 指令展示在受控管理界面时。', example: `const instructions = await interviewer.getInstructions({ requestContext })\nconsole.log(instructions)`, returns: '当前上下文下解析后的 AgentInstructions。', interview: 'instructions 负责行为引导，不提供强安全保证；安全必须由 tool schema、授权、processor 和执行层共同完成。', pitfall: '不要把用户原文直接拼进高权限指令；还要避免把密钥、内部规则或其他租户信息返回到前端。' }),
  mastraApi({ name: 'Agent.getLLM', group: 'Agent 智能体', kind: 'function', path: 'agents/getLLM', signature: 'agent.getLLM({ requestContext?, model? }?): Promise<LLM>', beginner: '取得 Agent 实际包装后的 LLM 执行器。它已经结合 Mastra 的模型解析和运行能力，比单纯的模型字符串更接近底层调用对象。', whenToUse: '实现框架扩展、诊断模型解析，或确实需要绕开 Agent 高层 generate/stream 使用底层 LLM 时。', example: `const llm = await interviewer.getLLM({ requestContext })\nconsole.log(llm.getModelId())`, returns: '解析完成的 LLM 实例。', interview: 'Agent 是策略与上下文层，LLM 是模型执行层；下沉到 LLM 会失去部分 Agent 工具、记忆和处理器编排。', pitfall: '普通业务优先调用 Agent API；直接调用 LLM 很容易绕过 guardrail、memory 或 observability 约定。' }),
  mastraApi({ name: 'Agent.getMemory', group: 'Agent 智能体', kind: 'function', path: 'agents/getMemory', signature: 'agent.getMemory({ requestContext? }?): Promise<Memory | undefined>', beginner: '解析 Agent 当前使用的 Memory。因为 memory 可以动态配置，不同请求可能拿到不同实例或没有记忆。', whenToUse: '手动管理线程、诊断记忆配置，或自定义操作必须与 Agent 使用同一 Memory 时。', example: `const memory = await interviewer.getMemory({ requestContext })\nconst thread = await memory?.getThreadById({ threadId })`, returns: 'Memory 实例或 undefined。', interview: '动态 Memory 允许多租户和分层存储，但每次解析必须依赖明确 requestContext，不能默认所有用户共享。', pitfall: '不要忽略 undefined；调用线程 API 时也要同时传 resourceId 做授权和隔离。' }),
  mastraApi({ name: 'Agent.getMetadata', group: 'Agent 智能体', kind: 'function', path: 'agents/getMetadata', signature: 'agent.getMetadata(): Record<string, unknown> | undefined', beginner: '读取 Agent 上附加的业务元数据，例如版本、负责人、标签或风险等级；这些数据不直接改变模型推理。', whenToUse: '构建 Agent 目录、治理面板、路由规则或审计信息时。', example: `const metadata = interviewer.getMetadata()\nconsole.log(metadata?.owner)`, returns: '元数据对象或 undefined。', interview: 'metadata 是控制面信息，适合治理和发现；运行时行为仍应由明确配置决定，不能把关键安全策略只藏在自由格式 metadata。', pitfall: '不要在 metadata 放 API key；也不要假设任意字段存在，读取前需要类型收窄。' }),
  mastraApi({ name: 'Agent.getModel', group: 'Agent 智能体', kind: 'function', path: 'agents/getModel', signature: 'agent.getModel({ requestContext?, model? }?): Promise<MastraLanguageModel>', beginner: '解析本次运行真正使用的模型。Agent 的 model 可以是固定字符串，也可以根据请求上下文动态选择。', whenToUse: '调试模型路由、显示当前模型、做成本策略或在运行前检查模型能力时。', example: `const model = await interviewer.getModel({ requestContext })\nconsole.log(model)`, returns: '解析后的 MastraLanguageModel。', interview: '动态模型路由可按任务、租户和成本选择模型，但要保证能力兼容、可追踪和故障回退。', pitfall: '不要只记录 Agent 名而不记录最终模型 id；否则质量或费用变化时无法追溯。' }),
  mastraApi({ name: 'createSkill', group: 'Agent 智能体', kind: 'function', path: 'agents/createSkill', signature: 'createSkill(config: SkillConfig): Skill', beginner: '创建一个可按需加载的技能包，把说明、文件和工具组织成 Agent 能发现和使用的专项能力。Skill 更像“操作手册 + 资源”，Tool 更像一个可执行函数。', whenToUse: 'Agent 有大量领域知识或流程，不希望每次都把全部说明塞进 system prompt 时。', example: `const interviewSkill = createSkill({\n  id: 'frontend-interview',\n  description: '回答前端面试题并给出追问',\n  instructions: '先讲直觉，再讲原理与案例。',\n})`, returns: '一个可注册到 Agent 的 Skill。', interview: 'Skill 通过按需发现减少常驻上下文，并把知识与执行能力模块化；它不是模型训练，也不会自动保证内容新鲜。', pitfall: '技能描述决定检索与选择质量；说明过宽会误触发，文件来源和工具权限也必须审核。' }),
  mastraApi({ name: 'Agent.getSkill', group: 'Agent 智能体', kind: 'function', path: 'agents/getSkill', signature: 'agent.getSkill(id: string): Skill | undefined', beginner: '按技能 id 取出 Agent 已配置的某个 Skill，用于查看说明或手动加载相关能力。', whenToUse: '调试技能发现、构建技能管理页，或业务代码明确知道要使用哪个技能时。', example: `const skill = interviewer.getSkill('frontend-interview')\nif (!skill) throw new Error('技能未配置')`, returns: '匹配 Skill 或 undefined。', interview: 'Skill 查找只是能力发现，真正使用仍涉及把说明/资源放入上下文以及执行工具；这两步需要可观测。', pitfall: '不要把来自用户的任意 id 直接用于加载高权限技能；需做允许列表与租户校验。' }),
  mastraApi({ name: 'Agent.getTools', group: 'Agent 智能体', kind: 'function', path: 'agents/getTools', signature: 'agent.getTools({ requestContext? }?): Promise<Record<string, ToolAction>>', beginner: '解析 Agent 在当前请求中真正可用的工具。tools 可以是动态函数，所以结果可能随用户、租户或上下文变化。', whenToUse: '调试工具暴露、实现权限过滤，或构建当前 Agent 的工具目录时。', example: `const tools = await interviewer.getTools({ requestContext })\nconsole.log(Object.keys(tools))`, returns: '工具名到 ToolAction 的映射。', interview: '动态工具集是最小权限的重要实现点：模型只应看到当前任务和用户真正允许的工具。', pitfall: '不要全局缓存动态结果；也不要仅靠“没告诉模型”保护危险工具，execute 层仍必须鉴权。' }),
  mastraApi({ name: 'Agent.listScorers', group: 'Agent 智能体', kind: 'function', path: 'agents/listScorers', signature: 'agent.listScorers(): Record<string, MastraScorer>', beginner: '列出直接配置在这个 Agent 上的评分器，表示它生成结果后可以用哪些质量维度评估。', whenToUse: 'Agent 评测页面、回归测试或检查 scorer 装配时。', example: `const scorers = interviewer.listScorers()`, returns: '评分器名字到 MastraScorer 的映射。', interview: 'Agent 级 scorer 更贴近任务语义；全局 scorer 适合通用标准，两者可组合但阈值要分别校准。', pitfall: '不要把评分器存在等同于每次自动执行；确认调用链和采样策略，否则只配置不评测。' }),
  mastraApi({ name: 'Agent.listSkills', group: 'Agent 智能体', kind: 'function', path: 'agents/listSkills', signature: 'agent.listSkills(): Record<string, Skill>', beginner: '列出 Agent 的所有技能，帮助你理解它“会哪些领域任务”，但不会因此立刻把所有技能内容塞进上下文。', whenToUse: '技能目录、治理、测试和调试按需加载行为时。', example: `const skills = interviewer.listSkills()\nconsole.log(Object.keys(skills))`, returns: '技能 id/名字到 Skill 的映射。', interview: '技能目录是能力发现层；规模变大后应做搜索、排序和权限过滤，避免把整个目录无脑交给模型。', pitfall: '不要向不可信客户端返回技能内部文件或提示词；只暴露经过筛选的描述元数据。' }),
  mastraApi({ name: 'Agent.listTools', group: 'Agent 智能体', kind: 'function', path: 'agents/listTools', signature: 'agent.listTools(): Record<string, ToolAction>', beginner: '列出 Agent 静态配置的工具，与 getTools 的动态解析不同，它更适合快速查看定义层有哪些工具。', whenToUse: '静态资源检查、Studio 展示和测试 Agent 配置时。', example: `const configured = interviewer.listTools()`, returns: '返回工具名称到 ToolAction 实例的完整静态配置映射。', interview: '区分“配置态工具目录”和“请求态可用工具集”；权限过滤通常发生在后者。', pitfall: '不要把 listTools 结果直接当当前用户的授权结果；动态 tools 与请求策略可能还会增删。' }),
  mastraApi({ name: 'Agent.listWorkflows', group: 'Agent 智能体', kind: 'function', path: 'agents/listWorkflows', signature: 'agent.listWorkflows(): Record<string, Workflow>', beginner: '列出可由该 Agent 使用或委派的 Workflow，让自主决策可以调用确定性流程。', whenToUse: 'Supervisor、管理界面或测试需要检查 Agent 能启动哪些流程时。', example: `const workflows = interviewer.listWorkflows()`, returns: 'Workflow 名到实例的映射。', interview: 'Agent 负责开放式决策，Workflow 负责可审计的确定性编排；把复杂高风险动作封装为 Workflow 能收紧控制面。', pitfall: '不要把所有全局 Workflow 自动暴露给 Agent；每条流程的输入权限和副作用都应单独审核。' }),
  mastraApi({ name: 'Agent.network', group: 'Agent 智能体', kind: 'function', path: 'agents/network', signature: 'agent.network(messages, options?): Promise<NetworkResult>', beginner: '让一个 Supervisor Agent 在多个 Agent、Tool 和 Workflow 之间做动态委派，直到完成任务。它解决的是“谁来做下一步”，而不是固定流程图。', whenToUse: '任务开放、步骤无法预先写死，并且多个专长 Agent 需要协作时。', example: `const result = await supervisor.network('分析候选人并生成面试计划', {\n  agents: { resumeAnalyst, interviewer },\n  workflows: { scheduleFlow },\n  maxSteps: 8,\n})`, returns: '网络执行结果，包含最终文本以及多步路由、工具或子 Agent 运行信息。', interview: 'Supervisor 模式用模型做动态路由，灵活但不确定；应通过清晰 description、maxSteps、预算、追踪和人工审批约束。', pitfall: '不要用 network 替代本来可以固定编排的流程；Agent 数量越多，路由成本、上下文长度和错误传播越明显。' }),
]

const toolApis = [
  mastraApi({ name: 'createTool', group: 'Tool 与 MCP', kind: 'function', path: 'tools/create-tool', signature: 'createTool<TInput, TOutput>(config: ToolConfig): ToolAction', beginner: '把普通 TypeScript 函数包装成模型能理解和安全调用的工具。id/description 告诉模型何时选它，inputSchema 校验参数，execute 才执行真实业务。', whenToUse: 'Agent 需要查询 API、数据库、搜索文档或执行受控业务动作时。', example: `const weatherTool = createTool({\n  id: 'get-weather',\n  description: '查询指定城市天气',\n  inputSchema: z.object({ city: z.string() }),\n  outputSchema: z.object({ temperature: z.number() }),\n  execute: async ({ context: { city } }) => fetchWeather(city),\n})`, returns: '类型化 ToolAction，可注册给 Agent、Mastra 或转换到 MCP。', interview: 'Tool calling 是模型生成结构化“调用意图”，框架校验后由应用执行；模型本身没有直接访问数据库或网络。', pitfall: 'description 不是鉴权，schema 也不验证业务权限；execute 内必须做授权、幂等、超时、审计和敏感输出裁剪。' }),
  mastraApi({ name: 'createVectorQueryTool', group: 'Tool 与 MCP', kind: 'function', path: 'tools/vector-query-tool', signature: 'createVectorQueryTool(config: VectorQueryToolConfig): ToolAction', beginner: '创建一个给 Agent 使用的向量检索工具：它把问题转成 embedding，到指定 vector store 找相似文档，再把结果交回模型。', whenToUse: '希望 Agent 自主决定何时查企业知识库，而不是每次请求都固定检索时。', example: `const knowledgeTool = createVectorQueryTool({\n  id: 'search-knowledge',\n  vectorStoreName: 'knowledgeBase',\n  indexName: 'docs',\n  model: 'openai/text-embedding-3-small',\n})`, returns: '一个输入查询文本、输出相似文档结果的 ToolAction。', interview: '它把 RAG retrieval 封装成 Tool；Agentic RAG 的优点是按需检索，代价是模型可能不查、查错或重复查。', pitfall: 'embedding 模型和索引维度必须一致；还要设置 topK、metadata 租户过滤并防止检索内容中的提示注入。' }),
  mastraApi({ name: 'createDocumentChunkerTool', group: 'Tool 与 MCP', kind: 'function', path: 'tools/document-chunker-tool', signature: 'createDocumentChunkerTool(config?: DocumentChunkerToolConfig): ToolAction', beginner: '把文档切块能力包装成 Tool，让 Agent 可以按格式和策略把长文本拆成适合 embedding 或处理的小段。', whenToUse: '文档入库流程由 Agent 驱动，或需要让模型选择 chunk 策略时。', example: `const chunker = createDocumentChunkerTool({\n  defaultStrategy: 'recursive',\n  defaultOptions: { maxSize: 800, overlap: 100 },\n})`, returns: '一个返回文档 chunks 的 ToolAction。', interview: '切块决定检索粒度：块太小语义不足，太大召回不精确；overlap 用上下文冗余换边界连续性。', pitfall: '不要把任意大文件直接交给工具；先限制大小、解析格式，并为重复入库设计内容哈希和幂等。' }),
  mastraApi({ name: 'createGraphRAGTool', group: 'Tool 与 MCP', kind: 'function', path: 'tools/graph-rag-tool', signature: 'createGraphRAGTool(config: GraphRAGToolConfig): ToolAction', beginner: '把 GraphRAG 查询包装为 Agent 工具。它不仅看文本相似度，还利用实体或片段之间的图关系扩展相关上下文。', whenToUse: '知识问题需要跨文档、多跳关系或“某人与某项目如何关联”这类图结构推理时。', example: `const graphTool = createGraphRAGTool({\n  id: 'search-relations',\n  graph: graphRag,\n  topK: 5,\n})`, returns: '一个可由 Agent 调用并返回图增强检索结果的 ToolAction。', interview: 'GraphRAG 用结构关系补足纯向量相似度，提升多跳问题，但建图、更新、实体消歧和查询延迟更复杂。', pitfall: '不是所有知识库都需要图；关系抽取错误会被后续推理放大，必须保留来源并限制遍历深度。' }),
  mastraApi({ name: 'MCPClient', group: 'Tool 与 MCP', kind: 'class', path: 'tools/mcp-client', signature: 'new MCPClient(config: MCPClientConfig)', beginner: '连接一个或多个远程 MCP Server，把对方发布的 tools、resources 和 prompts 变成 Mastra 可使用的能力。', whenToUse: '工具由独立服务、桌面应用或第三方 MCP 服务提供，不希望在当前进程重复实现时。', example: `const mcp = new MCPClient({\n  id: 'company-mcp',\n  servers: { docs: { url: new URL(process.env.MCP_URL!) } },\n})\nconst tools = await mcp.getTools()`, returns: 'MCPClient 实例，可发现工具、资源和提示，并管理连接。', interview: 'MCP 标准化“能力发现 + schema + 调用传输”，但不自动解决服务信任、身份认证和细粒度授权。', pitfall: '远程工具描述和返回内容都应视为不可信输入；配置连接超时、重连、允许列表，并在退出时关闭连接。' }),
  mastraApi({ name: 'MCPServer', group: 'Tool 与 MCP', kind: 'class', path: 'tools/mcp-server', signature: 'new MCPServer(config: MCPServerConfig)', beginner: '把本地 Mastra tools、resources 或 prompts 通过 MCP 协议发布出去，让其他兼容客户端发现和调用。', whenToUse: '要把内部 AI 能力做成跨应用复用的标准服务时。', example: `const server = new MCPServer({\n  id: 'interview-mcp',\n  name: 'Interview Tools',\n  version: '1.0.0',\n  tools: { searchQuestions },\n})`, returns: '一个可绑定 transport 并启动的 MCP Server 实例。', interview: 'MCP Server 是能力边界，不是简单 RPC 暴露；schema、版本、身份、审计和取消语义决定能否生产使用。', pitfall: '不要把内部所有工具默认发布；对有副作用的调用加入鉴权、审批和幂等键，并避免把异常堆栈直接返回客户端。' }),
]

const workflowApis = [
  mastraApi({ name: 'createWorkflow', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow', signature: 'createWorkflow(config: WorkflowConfig): Workflow', beginner: '创建一张有 inputSchema、outputSchema 和可选 stateSchema 的流程图骨架。随后用 then、branch、parallel 等方法连步骤，最后 commit 才完成定义。', whenToUse: '步骤和分支可以明确描述，需要可恢复、可审计、可测试的确定性业务流程时。', example: `const flow = createWorkflow({\n  id: 'interview-flow',\n  inputSchema: z.object({ topic: z.string() }),\n  outputSchema: z.object({ report: z.string() }),\n}).then(askStep).then(reportStep).commit()`, returns: '可继续链式编排并最终 commit 的 Workflow。', interview: 'Workflow 是有类型 schema 的状态机/有向图；它与 Agent 的区别是控制流由代码决定，而不是每步交给模型自由选择。', pitfall: '定义后忘记 commit 会得到不完整流程；每个相邻步骤的输出与输入 schema 必须兼容。' }),
  mastraApi({ name: 'createStep', group: 'Workflow 编排', kind: 'function', path: 'workflows/step', signature: 'createStep(config | tool | agent, options?): Step', beginner: '把一小段工作定义成 Workflow 节点。每个 Step 都声明输入、输出和 execute；也能直接把 Tool 或 Agent 包装成步骤。', whenToUse: '需要把业务拆成可复用、可验证、可重试的最小执行单元时。', example: `const normalize = createStep({\n  id: 'normalize',\n  inputSchema: z.object({ text: z.string() }),\n  outputSchema: z.object({ text: z.string() }),\n  execute: async ({ inputData }) => ({ text: inputData.text.trim() }),\n})`, returns: '类型化 Step，可接入 Workflow。', interview: 'Step 是数据契约 + 执行函数；schema 让图连接在开发期可检查，运行时也能阻止脏数据继续传播。', pitfall: 'execute 应尽量幂等；外部副作用需要幂等键，因为恢复、重试或 time travel 可能再次执行步骤。' }),
  mastraApi({ name: 'Run', group: 'Workflow 编排', kind: 'class', path: 'workflows/run', signature: 'workflow.createRun(options?): Promise<Run>', beginner: 'Run 代表 Workflow 的“一次具体执行”，保存 runId、状态、快照和暂停点。Workflow 像菜谱，Run 像这一次做菜的过程。', whenToUse: '启动、暂停恢复、取消或查看某一次流程执行时。', example: `const run = await flow.createRun({ runId: crypto.randomUUID() })\nconst result = await run.start({ inputData })`, returns: '独立 Run 实例，提供 start、resume、cancel、restart、timeTravel 等方法。', interview: '把定义与实例分离能让同一 Workflow 并发运行，并通过 runId 持久化和恢复每次执行状态。', pitfall: '不要跨业务请求复用 Run；runId 应稳定且唯一，恢复时还要校验 resourceId/租户归属。' }),
  mastraApi({ name: 'WorkflowStateReader', group: 'Workflow 编排', kind: 'class', path: 'workflows/workflow-state-reader', signature: 'new WorkflowStateReader(options: WorkflowStateReaderOptions)', beginner: '以只读方式查看 Workflow 当前 state，让步骤或外部代码读取共享状态，而不是随意修改快照。', whenToUse: '复杂流程需要根据共享 state 做诊断、展示或只读决策时。', example: `const reader = new WorkflowStateReader({ workflow, runId })\nconst state = await reader.getState()`, returns: '可读取 Workflow state 的对象。', interview: '只读状态视图减少并发写冲突；状态修改应经过 Workflow 执行语义，保证快照和恢复一致。', pitfall: '不要把读取到的对象当作可安全原地修改的实时状态；跨步骤更新应使用官方 state 机制。' }),
  mastraApi({ name: 'Workflow.then', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/then', signature: 'workflow.then(step: Step): Workflow', beginner: '把下一个 Step 串在当前节点之后，前一步输出会成为后一步输入。', whenToUse: '步骤必须按固定顺序依次执行时。', example: `const flow = createWorkflow(config)\n  .then(fetchStep)\n  .then(summarizeStep)\n  .commit()`, returns: '同一个 Workflow builder，便于继续链式调用。', interview: 'then 表示确定性的顺序依赖；类型系统会检查上一步 outputSchema 是否能喂给下一步 inputSchema。', pitfall: '不要用共享全局变量在步骤间传值；应通过 schema 化输出传递，才能正确快照与恢复。' }),
  mastraApi({ name: 'Workflow.branch', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/branch', signature: 'workflow.branch(branches: Array<[Condition, Step]>): Workflow', beginner: '根据输入或上下文判断走哪条分支；每个分支由条件和对应 Step 组成。', whenToUse: '流程有互斥或条件路径，例如分数高走深挖、分数低走基础题时。', example: `workflow.branch([\n  [async ({ inputData }) => inputData.score >= 80, advancedStep],\n  [async () => true, basicStep],\n])`, returns: '加入分支后的 Workflow builder。', interview: 'branch 把业务决策显式代码化，比让模型自由选择更可测试；条件顺序、默认分支和输出汇合契约必须明确。', pitfall: '确保至少一条条件能匹配；多个条件同时为真时要理解官方选择语义，并让各分支输出可被后续步骤接收。' }),
  mastraApi({ name: 'Workflow.parallel', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/parallel', signature: 'workflow.parallel(steps: Step[]): Workflow', beginner: '让多个互不依赖的 Step 同时执行，等全部完成后把结果汇合。', whenToUse: '多个 I/O 任务彼此独立，例如同时做简历分析、题库检索和公司资料查询时。', example: `workflow.parallel([resumeStep, questionStep, companyStep])`, returns: '并行节点加入后的 Workflow builder，后续收到按步骤组织的结果。', interview: 'parallel 缩短关键路径但提高瞬时并发；要讨论失败聚合、限流、资源竞争和结果 schema。', pitfall: '有数据依赖的步骤不能并行；外部 API 还要控制并发和重试，避免放大流量。' }),
  mastraApi({ name: 'Workflow.map', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/map', signature: 'workflow.map(mapping: MappingConfig): Workflow', beginner: '在不执行外部副作用的情况下重新整理当前数据形状，把前一步输出映射成下一步需要的输入。', whenToUse: '两个 Step 的字段名或结构不同，需要显式转换、选取常量或读取 workflow state 时。', example: `workflow.map(({ inputData }) => ({\n  prompt: inputData.question,\n  level: 'beginner',\n}))`, returns: '带数据映射节点的 Workflow builder。', interview: 'map 是图中的适配层，让 Step 保持独立契约，避免为了连接流程而修改可复用步骤。', pitfall: '不要在 map 做网络请求或不可重放副作用；复杂业务应建成独立 Step 以便追踪和重试。' }),
  mastraApi({ name: 'Workflow.foreach', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/foreach', signature: 'workflow.foreach(step: Step, options?: { concurrency?: number }): Workflow', beginner: '对输入数组里的每一项执行同一个 Step，并可限制同时处理多少项。', whenToUse: '批量处理文档、候选人或题目，每项逻辑相同且需要受控并发时。', example: `workflow.foreach(scoreCandidateStep, { concurrency: 4 })`, returns: '加入批处理节点的 Workflow builder，输出每一项的处理结果集合。', interview: 'foreach 是有并发上限的 fan-out/fan-in；要处理顺序映射、部分失败、重试和背压。', pitfall: '不要对大数组使用无限并发；步骤有副作用时还要提供逐项幂等键。' }),
  mastraApi({ name: 'Workflow.dowhile', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/dowhile', signature: 'workflow.dowhile(step: Step, condition: Condition): Workflow', beginner: '先至少执行一次 Step，再检查条件；条件仍为 true 就继续循环。', whenToUse: '任务必须先尝试一次，再根据结果决定是否继续，例如生成后评分，不达标继续改写。', example: `workflow.dowhile(improveStep, async ({ inputData }) => inputData.score < 0.8)`, returns: '包含 do-while 循环的 Workflow builder。', interview: 'dowhile 保证一次执行，与 dountil 的终止条件方向不同；循环必须有业务上限和可观测退出原因。', pitfall: '只靠模型分数可能永不满足条件；在步骤或 state 中加入最大轮次、成本和时间上限。' }),
  mastraApi({ name: 'Workflow.dountil', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/dountil', signature: 'workflow.dountil(step: Step, condition: Condition): Workflow', beginner: '至少执行一次 Step，然后在条件变成 true 时停止；可以理解为“反复做，直到达标”。', whenToUse: '重试、迭代改写或轮询任务有清晰成功条件时。', example: `workflow.dountil(pollStep, async ({ inputData }) => inputData.status === 'done')`, returns: '包含 do-until 循环的 Workflow builder。', interview: 'dountil 的条件是终止条件；生产实现要同时设计成功、失败、超时和取消四种出口。', pitfall: '不要无间隔轮询外部服务；配合 sleep、最大轮次和不可重试错误分类。' }),
  mastraApi({ name: 'Workflow.sleep', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/sleep', signature: 'workflow.sleep(milliseconds | delayResolver): Workflow', beginner: '让流程暂停指定毫秒数，时间到后继续；延迟可以固定，也可以根据当前输入动态计算。', whenToUse: '退避重试、限速、等待外部系统或定时节奏控制时。', example: `workflow.then(requestStep).sleep(5_000).then(checkStep)`, returns: '加入延时节点后的 Workflow builder。', interview: '可持久化 Workflow 的 sleep 不应长期占用线程；框架通过快照/调度语义恢复执行，这是与普通 setTimeout 的差别。', pitfall: '不要用 sleep 盲目等待不确定事件；有回调或人工操作时优先 suspend/signal，并设计取消。' }),
  mastraApi({ name: 'Workflow.sleepUntil', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/sleepUntil', signature: 'workflow.sleepUntil(date | dateResolver): Workflow', beginner: '把流程暂停到某个绝对时间点，再继续后续步骤；与 sleep 的相对毫秒延迟不同，它表达的是明确日程。', whenToUse: '预约发送、截止时间、跨天任务或业务日程明确到具体日期时。', example: `workflow.sleepUntil(({ inputData }) => new Date(inputData.interviewAt))`, returns: '加入绝对时间等待节点后的 Workflow builder。', interview: 'sleepUntil 使用绝对时间语义，恢复时要考虑持久化调度、时区和服务停机后的补偿策略。', pitfall: 'Date 应统一用 UTC/ISO 保存；目标时间已过去、夏令时和重复调度都需要明确处理。' }),
  mastraApi({ name: 'Workflow.commit', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/commit', signature: 'workflow.commit(): Workflow', beginner: '告诉 Mastra：“流程图已经连完，可以校验并运行了。”没有 commit 的 builder 还处于定义阶段。', whenToUse: '完成所有 then、branch、parallel 等编排后，导出或注册 Workflow 之前。', example: `export const flow = createWorkflow(config)\n  .then(stepA)\n  .then(stepB)\n  .commit()`, returns: '提交后的可执行 Workflow。', interview: 'commit 是构建期与运行期边界，可在这里冻结图并检查步骤关系，类似编译流程定义。', pitfall: '修改链后必须确保最终结果仍被 commit；未提交或 schema 不闭合会在注册/执行时失败。' }),
  mastraApi({ name: 'Workflow.createRun', group: 'Workflow 编排', kind: 'function', path: 'workflows/workflow-methods/create-run', signature: 'workflow.createRun(options?: { runId?: string; resourceId?: string }): Promise<Run>', beginner: '从可复用 Workflow 定义创建一次独立执行。可以指定 runId 便于幂等和恢复，也可绑定 resourceId。', whenToUse: '每次启动新流程、恢复特定业务任务或需要提前拿到 runId 时。', example: `const run = await flow.createRun({\n  runId: job.id,\n  resourceId: user.id,\n})`, returns: 'Promise<Run>，随后用 start/startAsync 启动。', interview: 'createRun 只创建执行上下文，不等于已经开始；runId 是工作流状态、日志和恢复的关联键。', pitfall: '不要复用同一 runId 启动不同输入；外部提供的 runId 必须校验归属，防止读取或恢复他人任务。' }),
  mastraApi({ name: 'Run.start', group: 'Workflow 编排', kind: 'function', path: 'workflows/run-methods/start', signature: 'run.start({ inputData }): Promise<WorkflowResult>', beginner: '启动 Run 并等待流程走到成功、失败、暂停或其他终态，然后一次返回结果。', whenToUse: '调用方需要同步等待完整流程结果，且执行时长适合当前请求生命周期时。', example: `const result = await run.start({ inputData: { topic: 'React' } })\nif (result.status === 'success') console.log(result.result)`, returns: 'WorkflowResult，包含 status、result、steps、error 或 suspend 数据。', interview: 'start 是等待型入口；长任务通常应 startAsync 并通过状态/流更新，避免占住 HTTP 连接。', pitfall: '必须按 status 做穷举处理，不能假设一定 success；设置超时不等于取消后台执行。' }),
  mastraApi({ name: 'Run.startAsync', group: 'Workflow 编排', kind: 'function', path: 'workflows/run-methods/startAsync', signature: 'run.startAsync({ inputData }): Promise<StartAsyncResult>', beginner: '把 Workflow 作为后台任务启动，调用方快速拿到执行标识，而不是一直等待最终结果。', whenToUse: '流程可能运行几分钟、跨人工审批或需要前端轮询/订阅状态时。', example: `const { runId } = await run.startAsync({ inputData })\nreturn Response.json({ runId }, { status: 202 })`, returns: '异步启动结果（包括 runId 等跟踪信息）；最终状态需要另行查询或订阅。', interview: 'startAsync 将提交任务与获取结果解耦，API 通常返回 202；生产必须提供状态机、幂等提交和失败补偿。', pitfall: '不要启动后丢失 runId；还要处理重复请求、队列拒绝和任务实际未被调度的情况。' }),
  mastraApi({ name: 'Run.resume', group: 'Workflow 编排', kind: 'function', path: 'workflows/run-methods/resume', signature: 'run.resume(resumeData, options?): Promise<WorkflowResult>', beginner: '给暂停中的 Workflow 提供人工答案或外部数据，让它从 suspend 点继续，而不是从头再跑。', whenToUse: '审批、人机协作、等待表单或外部信号后继续流程时。', example: `const result = await run.resume({ approved: true }, { step: 'approval' })`, returns: '继续执行后的 WorkflowResult；可能完成、再次暂停或失败。', interview: 'resume 依赖持久化快照恢复执行上下文；resumeData 是暂停点声明的输入契约，不是任意对象。', pitfall: '验证 run/step 仍处于可恢复状态、用户有审批权，并用幂等键防止重复点击执行两次。' }),
  mastraApi({ name: 'Run.cancel', group: 'Workflow 编排', kind: 'function', path: 'workflows/run-methods/cancel', signature: 'run.cancel(): Promise<void>', beginner: '请求取消某次 Workflow Run，使后续步骤不再继续，并让可取消的当前工作尽快停止。', whenToUse: '用户撤销任务、超时、资源预算耗尽或系统关闭时。', example: `await run.cancel()`, returns: '取消请求完成的 Promise；不返回业务结果。', interview: '取消通常是协作式而非强杀：运行器传播取消信号，步骤和外部请求必须支持 AbortSignal 才能及时响应。', pitfall: '不要承诺已经发生的外部副作用会自动回滚；需设计补偿动作并把取消做成幂等操作。' }),
  mastraApi({ name: 'Run.restart', group: 'Workflow 编排', kind: 'function', path: 'workflows/run-methods/restart', signature: 'run.restart(options?): Promise<WorkflowResult>', beginner: '重新启动某次执行，通常用于失败后从合适位置再次运行，并保留 Run 的关联信息。', whenToUse: '故障已修复、输入无需改变，希望重新执行失败流程时。', example: `const result = await run.restart()`, returns: '重新执行后的 WorkflowResult。', interview: 'restart 与 resume 不同：resume 从 suspend 点继续，restart 是重新执行语义；副作用步骤必须可幂等或可补偿。', pitfall: '不要对支付、发信等非幂等步骤盲目 restart；先确认官方重启范围和已有步骤快照。' }),
  mastraApi({ name: 'Run.timeTravel', group: 'Workflow 编排', kind: 'function', path: 'workflows/run-methods/timeTravel', signature: 'run.timeTravel(options: TimeTravelOptions): Promise<WorkflowResult>', beginner: '从历史某个步骤或快照重新执行后半段，用来修复数据、调试或重新计算，而不用从第一步开始。', whenToUse: '已保存运行快照，需要从指定节点重放后续流程时。', example: `const result = await run.timeTravel({ step: 'generate-report', inputData: corrected })`, returns: '从指定位置重放后的 WorkflowResult。', interview: 'time travel 是事件/快照驱动工作流的高级能力；重放确定性和外部副作用隔离是设计重点。', pitfall: '重放可能再次发送邮件或写数据库；对副作用步骤使用幂等键、模拟模式或显式跳过策略。' }),
  mastraApi({ name: 'Workflow.stream', group: 'Workflow 编排', kind: 'function', path: 'streaming/workflows/stream', signature: 'run.stream({ inputData }): Promise<WorkflowStreamResult>', beginner: '启动 Workflow 并实时输出步骤开始、完成、暂停、错误和结果等事件，前端不必等全部结束。', whenToUse: '长流程进度条、实时日志、Agent 步骤流或用户需要看到执行进展时。', example: `const stream = await run.stream({ inputData })\nfor await (const event of stream) handleWorkflowEvent(event)`, returns: '可异步迭代的 Workflow 事件流及最终状态。', interview: 'Workflow 流是结构化状态事件，不应退化成纯文本；客户端需要按 runId 和事件类型更新状态机。', pitfall: '网络断线不代表工作流停止；前端应能通过 runId 重连、补拉快照并去重事件。' }),
  mastraApi({ name: 'Workflow.observeStream', group: 'Workflow 编排', kind: 'function', path: 'streaming/workflows/observeStream', signature: 'run.observeStream(callback): Promise<Unsubscribe>', beginner: '订阅某次 Run 的事件并用回调观察进度，适合服务端把事件转发到日志、WebSocket 或内部监控。', whenToUse: '已有 Run 正在执行，需要旁路监听而不是再次启动它时。', example: `const unsubscribe = await run.observeStream(event => audit(event))\n// 不再需要时\nunsubscribe()`, returns: '取消订阅函数或等价句柄。', interview: '观察者不应改变 Workflow 业务结果；它属于控制面/可观测性，必须处理慢消费者和重复事件。', pitfall: '生命周期结束要取消订阅，避免内存泄漏；回调异常也不能反向破坏主流程。' }),
  mastraApi({ name: 'Workflow.resumeStream', group: 'Workflow 编排', kind: 'function', path: 'streaming/workflows/resumeStream', signature: 'run.resumeStream(resumeData, options?): Promise<WorkflowStreamResult>', beginner: '像 resume 一样继续暂停流程，但把继续后的每个事件实时流出来。', whenToUse: '用户完成审批后，界面仍要持续展示后续执行进度时。', example: `const stream = await run.resumeStream({ approved: true }, { step: 'approval' })\nfor await (const event of stream) send(event)`, returns: '恢复执行后的 Workflow 事件流。', interview: 'resumeStream 同时涉及状态恢复与传输恢复；业务幂等由 run/step 保证，网络重连由事件协议保证。', pitfall: '重复提交 resumeData 可能重复副作用；服务端应校验暂停点并记录审批幂等键。' }),
  mastraApi({ name: 'Workflow.timeTravelStream', group: 'Workflow 编排', kind: 'function', path: 'streaming/workflows/timeTravelStream', signature: 'run.timeTravelStream(options): Promise<WorkflowStreamResult>', beginner: '从历史步骤重放 Workflow，并实时观察重放后的每个状态事件。', whenToUse: '调试、修复或重新计算时既要 time travel，又要向操作界面展示详细进度。', example: `const stream = await run.timeTravelStream({ step: 'score' })\nfor await (const event of stream) console.log(event)`, returns: '从指定位置重放产生的 Workflow 事件流。', interview: '这是重放语义和事件流语义的组合；可审计系统应标记事件来自原始运行还是 time-travel 分支。', pitfall: '不要让普通用户任意重放生产副作用；限制权限，隔离输出并记录操作者、起点和原因。' }),
]

const memoryApis = [
  mastraApi({ name: 'Memory', group: 'Memory 记忆', kind: 'class', path: 'memory/memory-class', signature: 'new Memory(config: MemoryConfig)', beginner: 'Memory 为 Agent 管理对话线程、消息历史、工作记忆、语义召回和观测记忆。它决定“取哪些过去信息放回本轮上下文”，底层 Storage 才负责把数据真正保存在哪里。', whenToUse: '聊天需要跨轮保持上下文，或希望按用户/线程召回历史和长期信息时。', example: `const memory = new Memory({\n  storage,\n  vector,\n  embedder: 'openai/text-embedding-3-small',\n  options: { lastMessages: 20, semanticRecall: true },\n})`, returns: 'Memory 实例，可配置给 Agent 并直接管理 thread/message。', interview: 'Memory 不是把全部历史无限塞给模型，而是“存储 + 检索 + 裁剪 + 注入”的上下文工程；要在相关性、token、隐私和时效之间权衡。', pitfall: '生产必须配置持久化；resourceId 与 threadId 都要参与隔离。语义召回还要求 embedding 模型、向量维度和索引一致。' }),
  mastraApi({ name: 'ObservationalMemory', group: 'Memory 记忆', kind: 'class', path: 'memory/observational-memory', signature: 'new ObservationalMemory(config: ObservationalMemoryConfig)', beginner: '让一个 Observer 模型把长对话压缩成“观察笔记”，再由 Reflector 整理，Agent 不必每轮读取所有原始消息。', whenToUse: '会话很长、需要跨数百轮保持重要事实，又要控制上下文 token 时。', example: `const observationalMemory = new ObservationalMemory({\n  model: 'openai/gpt-5-mini',\n  observation: { messageTokens: 20_000 },\n})`, returns: '可接入 Memory 配置的观测记忆处理器。', interview: '它用有损摘要换取长上下文可扩展性；观察阈值触发压缩，反思阶段再合并旧观察，因此要监控事实丢失和摘要漂移。', pitfall: '不要把摘要当事实数据库；关键业务字段应结构化保存。Observer 也会产生模型成本，并可能把错误长期固化。' }),
  mastraApi({ name: 'summarizeConversation', group: 'Memory 记忆', kind: 'function', path: 'memory/summarizeConversation', signature: 'summarizeConversation(options): Promise<ConversationSummaryResult>', beginner: '对手头已有的消息做一次性总结并可提取结构化字段。它不会读取 Memory，也不会自动写回存储，结果由调用方决定保存到哪里。', whenToUse: '语音结束、客服会话归档或批处理已有消息，需要明确控制总结与落库时。', example: `const { summary, extracted } = await summarizeConversation({\n  model: 'openai/gpt-5-mini',\n  messages,\n  instructions: '总结面试表现并列出薄弱知识点。',\n})`, returns: 'summary、extracted、extractionFailures 和 usage。', interview: '这是无状态的一次性归纳；与 Memory.summarizeThread 的区别是调用方提供消息且函数不读写线程存储。', pitfall: '总结是有损的；空消息、抽取失败和 token usage 都要处理，敏感对话发送模型前先做合规判断。' }),
  mastraApi({ name: 'Memory.createThread', group: 'Memory 记忆', kind: 'function', path: 'memory/createThread', signature: 'memory.createThread({ resourceId, threadId?, title?, metadata? }): Promise<StorageThreadType>', beginner: '创建一条独立会话线程，并把它归属到某个 resource（通常是用户或项目）。后续消息通过 threadId 聚在同一段对话中。', whenToUse: '开启新聊天、面试场次或长期任务上下文时。', example: `const thread = await memory.createThread({\n  resourceId: user.id,\n  title: 'React 模拟面试',\n})`, returns: '包含 id、resourceId、title、时间戳和 metadata 的线程对象。', interview: 'resourceId 表示所有者/资源，threadId 表示一次会话；二者组合才能支持一个用户多会话和多用户隔离。', pitfall: '不要只用前端传来的 threadId 判断权限；创建自定义 id 时保证唯一和不可猜测，并限制 metadata 敏感内容。' }),
  mastraApi({ name: 'Memory.getThreadById', group: 'Memory 记忆', kind: 'function', path: 'memory/getThreadById', signature: 'memory.getThreadById({ threadId }): Promise<StorageThreadType | null>', beginner: '按 threadId 读取线程的标题、归属、时间和 metadata；它读取的是线程记录，不等于把全部消息一起返回。', whenToUse: '打开会话、校验线程所有者或显示线程信息时。', example: `const thread = await memory.getThreadById({ threadId })\nif (!thread || thread.resourceId !== user.id) throw new Error('无权访问')`, returns: '线程对象；不存在时返回 null/空结果。', interview: '读取线程后还要做资源级授权；“知道 id”不能等同于“拥有访问权”。', pitfall: '不要在未检查 resourceId 前加载消息或恢复 Agent；避免 IDOR 越权。' }),
  mastraApi({ name: 'Memory.listThreads', group: 'Memory 记忆', kind: 'function', path: 'memory/listThreads', signature: 'memory.listThreads({ resourceId, page?, perPage?, orderBy? }): Promise<ThreadList>', beginner: '分页列出某个 resource 下的会话线程，常用于聊天侧边栏或历史面试列表。', whenToUse: '用户需要浏览、搜索或分页查看自己的多条会话时。', example: `const page = await memory.listThreads({\n  resourceId: user.id,\n  page: 0,\n  perPage: 20,\n})`, returns: '线程数组以及分页/总数信息。', interview: '列表必须以 resourceId 为服务端过滤条件，并使用稳定排序；数据量大时分页而不是全量加载。', pitfall: '不要让客户端覆盖成任意 resourceId；页码、每页数量要设上限，删除线程的显示也要定义一致性。' }),
  mastraApi({ name: 'Memory.recall', group: 'Memory 记忆', kind: 'function', path: 'memory/recall', signature: 'memory.recall({ threadId, resourceId?, vectorSearchString?, ... }): Promise<RecallResult>', beginner: '为当前一轮对话取回需要的历史：最近消息保证连续性，semantic recall 可根据查询找语义相近的旧内容。', whenToUse: '手动构建上下文、调试召回结果，或不通过 Agent.generate 也要使用 Memory 检索时。', example: `const recalled = await memory.recall({\n  threadId,\n  resourceId: user.id,\n  vectorSearchString: '候选人不熟悉的 React 知识点',\n})`, returns: '召回的消息、线程和相关上下文数据。', interview: 'Recall 往往是“最近窗口 + 语义检索”的混合策略；前者保连续，后者找远期相关信息，再受 token 预算裁剪。', pitfall: '语义相似不等于事实正确；必须过滤租户 metadata，并防止旧消息中的提示注入重新进入高权限上下文。' }),
  mastraApi({ name: 'Memory.deleteMessages', group: 'Memory 记忆', kind: 'function', path: 'memory/deleteMessages', signature: 'memory.deleteMessages(messageIds: string[]): Promise<void>', beginner: '按消息 id 删除一批已存消息，用于用户撤回、数据清理或合规请求。', whenToUse: '明确知道要删除哪些消息，并已完成所有权校验时。', example: `await memory.deleteMessages(selectedMessageIds)`, returns: '删除完成的 Promise。', interview: '删除消息涉及关系存储、向量索引和派生摘要的一致性；真正合规删除不能只删一张主表。', pitfall: '先校验消息属于当前 resource；还要确认 embedding、缓存、观测摘要和备份的保留/删除策略。' }),
  mastraApi({ name: 'Memory.cloneThread', group: 'Memory 记忆', kind: 'function', path: 'memory/cloneThread', signature: 'memory.cloneThread({ threadId, newThreadId?, resourceId?, ... }): Promise<ClonedThread>', beginner: '复制一条线程及选定历史，生成新的会话分支。原线程不变，新线程可以从相同上下文继续不同方向。', whenToUse: '对话分支、实验不同提示、从历史节点重新开始或复制模板会话时。', example: `const branch = await memory.cloneThread({\n  threadId,\n  newThreadId: crypto.randomUUID(),\n  resourceId: user.id,\n})`, returns: '新线程以及复制结果信息。', interview: '线程克隆类似 conversation fork；需要定义复制范围、消息身份、引用关系和后续两支独立写入语义。', pitfall: '克隆前验证源线程权限；避免复制敏感 metadata，并预估大量消息/向量复制的存储成本。' }),
  mastraApi({ name: 'Memory.summarizeThread', group: 'Memory 记忆', kind: 'function', path: 'memory/summarizeThread', signature: 'memory.summarizeThread({ threadId, resourceId?, ... }): Promise<ConversationSummaryResult>', beginner: '从存储中加载指定线程消息并做一次性总结；与 summarizeConversation 相比，你不必先自己把消息查出来。', whenToUse: '生成会话摘要、面试复盘或归档报告，消息已经保存在 Memory 中时。', example: `const result = await memory.summarizeThread({\n  threadId,\n  resourceId: user.id,\n  instructions: '提炼掌握点、薄弱点和下一步计划。',\n})`, returns: 'summary、结构化 extracted、失败信息和 token usage。', interview: '它是存储感知的总结入口，但总结结果是否写回业务库仍由应用决定；不要与自动 Observational Memory 混淆。', pitfall: '先验证线程归属；长线程总结会有成本和截断风险，生成报告时保存模型/提示版本以便追溯。' }),
]

const ragApis = [
  mastraApi({ name: 'DatabaseConfig', group: 'RAG 与 Vector', kind: 'type', maturity: 'type-only', path: 'rag/database-config', signature: 'type DatabaseConfig = { vectorStoreName; indexName; ... }', beginner: '描述 RAG 工具该去哪个已注册向量库、哪个索引查询，是把知识库位置从检索逻辑中抽出来的配置契约。', whenToUse: '配置 vector query、GraphRAG 或复用同一知识库定位信息时。', example: `const database: DatabaseConfig = {\n  vectorStoreName: 'knowledgeBase',\n  indexName: 'interview-docs',\n}`, returns: '仅 TypeScript 配置类型，运行时不会产生对象或执行查询。', interview: '显式数据库配置便于环境切换和多知识库路由，但访问控制不能只依赖字符串名字。', pitfall: '索引名、维度和租户过滤必须与实际 vector store 一致；不要让客户端任意覆盖配置。' }),
  mastraApi({ name: 'embed', group: 'RAG 与 Vector', kind: 'function', path: 'rag/embeddings', signature: 'embed({ model, value, maxRetries?, abortSignal?, headers? }): Promise<EmbedResult>', beginner: '把一段文字或对象转换为一个数字向量，语义相近的内容通常在向量空间更接近。Mastra 官方参考使用 AI SDK embed 配合 ModelRouterEmbeddingModel。', whenToUse: '给单条搜索问题生成 query vector，或写入一条文档向量时。', example: `const { embedding } = await embed({\n  model: new ModelRouterEmbeddingModel('openai/text-embedding-3-small'),\n  value: 'React useEffect 的清理时机',\n})`, returns: '包含 embedding:number[] 以及模型用量等信息的结果。', interview: 'Embedding 是语义编码，不是摘要或加密；查询与入库必须使用同一模型、维度和预处理，否则距离不可比较。', pitfall: '模型升级通常需要重嵌入历史数据；敏感文本发送第三方前要合规，失败重试也会增加费用。' }),
  mastraApi({ name: 'embedMany', group: 'RAG 与 Vector', kind: 'function', path: 'rag/embeddings', signature: 'embedMany({ model, values, maxRetries?, abortSignal?, headers? }): Promise<EmbedManyResult>', beginner: 'embed 的批量版，一次把多段文档转换成对应顺序的多个向量，更适合离线入库。', whenToUse: '文档切块后批量生成 embeddings，减少逐条请求开销时。', example: `const { embeddings } = await embedMany({\n  model: new ModelRouterEmbeddingModel('openai/text-embedding-3-small'),\n  values: chunks.map(chunk => chunk.text),\n})`, returns: '与 values 顺序对应的 number[][] embeddings 及 usage。', interview: '批处理要在吞吐、供应商批次限制、并发和失败重试间平衡，并保持 chunk 到 vector 的稳定位置映射。', pitfall: '不要把超大数组一次提交；分批后为每块保留稳定 id，避免部分失败重试造成重复写入。' }),
  mastraApi({ name: 'MDocument', group: 'RAG 与 Vector', kind: 'class', path: 'rag/document', signature: 'MDocument.fromText | fromHTML | fromMarkdown | fromJSON(content, metadata?)', beginner: '把不同格式原文统一包装成可切块的文档对象，并保留 metadata。之后可调用 chunk、getText、getDocs 和 extractMetadata。', whenToUse: 'RAG 入库前需要规范化纯文本、HTML、Markdown 或 JSON 文档时。', example: `const doc = MDocument.fromMarkdown(markdown, { source: 'react-guide' })\nconst chunks = await doc.chunk({ strategy: 'recursive', maxSize: 800, overlap: 100 })`, returns: 'MDocument 实例；chunk 后得到带文本和 metadata 的文档块。', interview: '文档抽象把解析、metadata 和切块统一，metadata 是后续来源引用、过滤和删除的重要主键。', pitfall: 'HTML/JSON 解析不等于内容可信；入库前去除脚本、重复导航和敏感字段，并保留 source/version。' }),
  mastraApi({ name: 'MDocument.chunk', group: 'RAG 与 Vector', kind: 'function', path: 'rag/chunk', signature: 'document.chunk(options: ChunkOptions): Promise<DocumentChunk[]>', beginner: '按 character、recursive、sentence、markdown、token 等策略把长文拆成小块，并可设置 maxSize 与 overlap。', whenToUse: '生成 embedding 前，或者模型上下文无法直接放入整篇长文时。', example: `const chunks = await doc.chunk({\n  strategy: 'recursive',\n  maxSize: 800,\n  overlap: 100,\n})`, returns: 'DocumentChunk 数组，每块包含 text 和继承/提取的 metadata。', interview: 'Chunking 是 RAG 质量的上游关键：粒度影响召回与上下文完整性，策略应按文档结构和查询类型评测。', pitfall: 'overlap 太大会产生重复答案和存储浪费；切块策略改变后需版本化并重建对应向量。' }),
  mastraApi({ name: 'ExtractParams', group: 'RAG 与 Vector', kind: 'type', maturity: 'type-only', path: 'rag/extract-params', signature: 'type ExtractParams = { title?; summary?; keywords?; questions?; ... }', beginner: '声明希望 MDocument 从文档中提取哪些派生信息，例如标题、摘要、关键词或假设问题，用于增强 metadata 与检索。', whenToUse: '入库管道需要自动补充可过滤字段或为文档生成检索提示时。', example: `const params: ExtractParams = {\n  title: true,\n  summary: true,\n  keywords: true,\n}`, returns: '仅类型化提取配置；实际结果由文档的 extractMetadata 等方法产生。', interview: '派生 metadata 能提升检索与展示，但它是模型/算法生成数据，必须记录来源和版本，不能冒充原文事实。', pitfall: '提取会增加成本；不要对每块重复生成昂贵摘要，也要处理缺失或错误字段。' }),
  mastraApi({ name: 'MetadataFilter', group: 'RAG 与 Vector', kind: 'type', maturity: 'type-only', path: 'rag/metadata-filters', signature: 'type MetadataFilter = Record<string, FilterValue | FilterOperator>', beginner: '用结构化条件限制向量查询只在符合 metadata 的文档中搜索，例如指定租户、文档类型、日期或权限标签。', whenToUse: '多租户 RAG、权限过滤、时间范围和分类检索时。', example: `const filter: MetadataFilter = {\n  tenantId: user.tenantId,\n  category: { $in: ['frontend', 'ai'] },\n}`, returns: '传给向量查询的过滤表达式，不会单独执行查询。', interview: 'metadata filter 不只是相关性优化，常常还是数据授权边界；过滤能力因向量数据库而异。', pitfall: '不能只在模型回答后过滤；必须在检索阶段加入服务端生成的租户条件，并测试适配器支持的操作符。' }),
  mastraApi({ name: 'GraphRAG', group: 'RAG 与 Vector', kind: 'class', path: 'rag/graph-rag', signature: 'new GraphRAG({ dimension?: number, threshold?: number })', beginner: '用文档块作为节点、语义相似关系作为边构建知识图，再结合向量相似度和随机游走寻找相关内容。', whenToUse: '问题需要跨多个片段发现关联、多跳上下文，而纯 topK 向量检索经常漏掉关系信息时。', example: `const graph = new GraphRAG({ dimension: 1536, threshold: 0.7 })\ngraph.createGraph(chunks, embeddings)\nconst results = await graph.query({ query: queryEmbedding, topK: 10 })`, returns: 'query 返回 RankedNode[]，含 id、content、metadata 和综合 score。', interview: 'GraphRAG 用图传播扩大相关上下文，threshold 决定建边稠密度，random walk 参数影响探索范围与成本。', pitfall: 'dimension 必须一致；阈值过低会形成噪声密图，过高会断开关系。大规模图的构建和更新成本也要评估。' }),
  mastraApi({ name: 'rerank', group: 'RAG 与 Vector', kind: 'function', path: 'rag/rerank', signature: 'rerank(results, query, model, options?): Promise<RerankedResult[]>', beginner: '对向量检索的候选结果做第二次更精细排序，让与问题真正相关的内容排到前面。', whenToUse: '向量检索召回率可以，但 topK 前几条噪声多，需要提高最终上下文精度时。', example: `const ranked = await rerank(candidates, query, rerankModel, { topK: 5 })`, returns: '按新相关性得分排序并裁剪后的结果。', interview: '标准是“两阶段检索”：廉价向量/关键词负责召回，昂贵 reranker 负责精排；质量提升以额外延迟和费用为代价。', pitfall: '不要把整个知识库送去 rerank；先控制候选集，并保留 original score/index 便于诊断。' }),
  mastraApi({ name: 'rerankWithScorer', group: 'RAG 与 Vector', kind: 'function', path: 'rag/rerankWithScorer', signature: 'rerankWithScorer(results, query, scorer, options?): Promise<RerankedResult[]>', beginner: '使用 Mastra Scorer 给候选文档逐项评分并重排，便于用自定义业务标准定义“相关”。', whenToUse: '通用 rerank 模型不符合领域标准，或已有定制 scorer、规则和评测逻辑时。', example: `const ranked = await rerankWithScorer(candidates, query, relevancyScorer, { topK: 5 })`, returns: '带 scorer 分数并按分数排序的候选结果。', interview: '可编程 scorer 让排序标准可解释、可评测，但 scorer 的一致性、吞吐和版本决定系统稳定性。', pitfall: '模型型 scorer 逐条执行可能很慢；使用并发上限、批处理和缓存，并处理某条评分失败。' }),
]

const observabilityApis = [
  mastraApi({ name: 'ObservabilityRegistryConfig', group: 'Observability 可观测性', kind: 'interface', maturity: 'type-only', path: 'observability/tracing/configuration', signature: 'interface ObservabilityRegistryConfig { configs?; default?; configSelector? }', beginner: '配置 Mastra 有哪些可观测性实例、哪一个默认启用，以及如何根据请求上下文选择实例。它是多环境、多租户 trace 路由的控制面。', whenToUse: '构造 Mastra 时启用 tracing，或需要将不同租户/环境的 trace 发往不同后端时。', example: `const mastra = new Mastra({\n  observability: {\n    default: { serviceName: 'interview-api', exporters: [exporter] },\n  },\n})`, returns: '配置类型本身无运行时返回；Mastra 据此创建 observability registry。', interview: '可观测性实例选择应在请求开始时稳定决定，trace 必须关联 agent/workflow、模型、token、错误和业务资源。', pitfall: '不要把 prompt 原文默认记录到所有 exporter；生产配置采样、脱敏、保留期和失败降级。' }),
  mastraApi({ name: 'DefaultObservabilityInstance', group: 'Observability 可观测性', kind: 'class', path: 'observability/tracing/instances', signature: 'new DefaultObservabilityInstance(config: ObservabilityInstanceConfig)', beginner: 'Mastra 提供的默认 tracing 实现，负责创建 trace/span，运行 processor，再把导出数据交给一个或多个 exporter。', whenToUse: '需要标准 Mastra trace 管线，不打算自己实现完整 ObservabilityInstance 时。', example: `const instance = new DefaultObservabilityInstance({\n  serviceName: 'interview-api',\n  exporters: [new ConsoleExporter()],\n})`, returns: '可注册和启动的 observability instance。', interview: '典型管线是 instrumentation → span → processor → exporter；业务请求不应因 exporter 暂时失败而整体失败。', pitfall: '启动和 shutdown 生命周期要正确管理以 flush 缓冲；高流量必须采样并限制 attributes 大小。' }),
  mastraApi({ name: 'BaseSpan', group: 'Observability 可观测性', kind: 'class', path: 'observability/tracing/spans', signature: 'span.createChildSpan(...) | span.setAttribute(...) | span.end(...)', beginner: 'Span 表示一次有开始和结束的工作，例如一次 Agent 调用、模型请求或 Tool 执行；父子 span 连起来就是完整 Trace。', whenToUse: '自定义工具、路由或业务步骤需要加入现有 trace，记录耗时、状态和关键元数据时。', example: `const span = tracingContext.currentSpan?.createChildSpan({ name: 'load-profile' })\ntry {\n  span?.setAttribute('resource.id', resourceId)\n  await loadProfile()\n} finally {\n  span?.end()\n}`, returns: '子 Span 或对当前 Span 的链式更新；end 后形成可导出的记录。', interview: 'Trace 是一次端到端请求，Span 是其中一个时间区间；上下文传播决定跨异步边界能否正确建立父子关系。', pitfall: '必须在 finally 中 end；不要记录高基数或敏感属性，也不要修改已经结束的 span。' }),
  mastraApi({ name: 'SpanFilter', group: 'Observability 可观测性', kind: 'type', maturity: 'type-only', path: 'observability/tracing/span-filtering', signature: 'type SpanFilter = (span: ExportedSpan) => boolean', beginner: '在 span 导出前决定哪些记录保留、忽略或路由，避免把健康检查、噪声事件或敏感数据全部发送到后端。', whenToUse: '控制观测成本、去除低价值 span，或对不同类型 trace 应用不同 exporter 时。', example: `const filter: SpanFilter = span =>\n  span.name !== 'healthcheck' && span.attributes.environment === 'production'`, returns: '布尔判断：true 表示匹配该 span。', interview: '过滤与采样不同：采样通常决定整条 trace 是否记录，filter 可以在导出阶段按 span 内容细分；两者都影响可诊断完整性。', pitfall: '不要过滤掉所有错误或父 span；否则子 span 会失去上下文。过滤规则变化也应版本化和监控命中率。' }),
  mastraApi({ name: 'PinoLogger', group: 'Observability 可观测性', kind: 'class', path: 'logging/pino-logger', signature: 'new PinoLogger(config: PinoLoggerOptions)', beginner: '用 Pino 作为 Mastra 的结构化日志实现，支持日志级别、名称和 JSON 输出，便于日志平台检索。', whenToUse: 'Node.js 生产服务需要高性能结构化日志，并希望 Mastra 与业务共用同一 logger 时。', example: `const logger = new PinoLogger({\n  name: 'interview-api',\n  level: process.env.LOG_LEVEL ?? 'info',\n})\nconst mastra = new Mastra({ logger })`, returns: '实现 Mastra logger 接口的 PinoLogger 实例。', interview: '日志记录离散事件，trace 记录调用链和耗时；通过 traceId/runId 关联二者才能快速定位问题。', pitfall: '生产不要使用过低级别输出所有 prompt；字段脱敏、日志注入防护和异步 flush 都要配置。' }),
  mastraApi({ name: 'Observability.addFeedback', group: 'Observability 可观测性', kind: 'function', path: 'observability/feedback', signature: 'mastra.observability.addFeedback?.({ traceId, spanId?, feedback }): Promise<void>', beginner: '把用户点赞、评分、评论或纠正绑定到某条 trace/span，让“这次回答好不好”与真实执行记录关联。', whenToUse: '聊天点赞、人工 QA、纠错反馈和后续评测数据集建设时。', example: `await mastra.observability.addFeedback?.({\n  traceId,\n  spanId,\n  feedback: { feedbackSource: 'user', feedbackType: 'rating', value: 1 },\n})`, returns: '写入反馈完成的 Promise；该能力在 active implementation 上是可选的。', interview: '线上反馈是弱标签但价值很高；关联 trace 后可以回看模型、上下文、工具和延迟，并用于评测而非直接盲目训练。', pitfall: '先检查 addFeedback 是否存在；还要防刷、验证 trace 归属，并避免在评论中存储未脱敏个人信息。' }),
  mastraApi({ name: 'AutomaticMetrics', group: 'Observability 可观测性', kind: 'interface', maturity: 'type-only', path: 'observability/metrics/automatic-metrics', signature: 'automaticMetrics: { enabled?: boolean; ...metricOptions }', beginner: '让 Mastra 根据 trace 自动计算调用次数、延迟、错误和模型 token 等常用指标，不必每个 Agent/Tool 手写计数器。', whenToUse: '生产监控需要趋势、SLO、成本和错误率看板时。', example: `const observability = {\n  default: {\n    serviceName: 'interview-api',\n    metrics: { enabled: true },\n  },\n}`, returns: '配置启用后由 observability 管线产生指标数据；配置对象本身无业务返回值。', interview: 'Metrics 适合聚合趋势，Trace 适合单次诊断，Log 适合事件细节；三者通过共同维度关联但用途不同。', pitfall: '控制 label 基数，不能把 userId、完整 prompt 或 runId 当普通 metrics label，否则时序库成本会爆炸。' }),
]

export const MASTRA_FRAMEWORK_API_EXPECTED_COUNT = 101

export const mastraFrameworkApis: FrameworkApiReference[] = [
  ...coreApis,
  ...agentApis,
  ...toolApis,
  ...workflowApis,
  ...memoryApis,
  ...ragApis,
  ...observabilityApis,
]

if (mastraFrameworkApis.length !== MASTRA_FRAMEWORK_API_EXPECTED_COUNT) {
  throw new Error(`Mastra framework API catalog expected ${MASTRA_FRAMEWORK_API_EXPECTED_COUNT} entries, received ${mastraFrameworkApis.length}`)
}
